import 'package:dart_jsonwebtoken/dart_jsonwebtoken.dart';
import '../core/config/app_config.dart';

class TokenService {
  TokenService._();

  /// Generates a valid LiveKit Room Access Token.
  /// In production, tokens can be generated by your backend or Supabase Edge Function.
  /// For direct mobile & web client connectivity, this generates the standard signed JWT.
  static String createLiveKitToken({
    required String roomName,
    required String participantId,
    required String participantName,
  }) {
    if (!AppConfig.isLiveKitConfigured) {
      // Mock token for offline testing/development
      return 'mock_livekit_token_${participantId}_$roomName';
    }

    final jwt = JWT(
      {
        'sub': participantId,
        'name': participantName,
        'video': {
          'room': roomName,
          'roomJoin': true,
          'canPublish': true,
          'canSubscribe': true,
          'canPublishData': true,
        },
      },
      issuer: AppConfig.liveKitApiKey,
    );

    // LiveKit tokens use HMAC SHA256 with the API Secret
    final token = jwt.sign(
      SecretKey(AppConfig.liveKitApiSecret),
      algorithm: JWTAlgorithm.HS256,
      expiresIn: const Duration(hours: 4),
    );

    return token;
  }
}
